/**
 * End-to-end tests for DISTINCT/REDUCED planning on LMDB index order: results must always equal a MemoryStore, and the
 * default (non-native) path must plan the leading pattern on an index order without moving any join argument.
 */
class LmdbDistinctStableOrderPlanningTest {

	private static final String FORCE_ROOT_GENERIC = "rdf4j.lmdb.nativeQueryEngine.forceRootGeneric";
	private static final String P = "<urn:p>";
	private static final String Q = "<urn:q>";

	private static final String FILTER_DISTINCT = "SELECT DISTINCT ?a ?c WHERE { ?a " + P + " ?b . ?b " + Q
			+ " ?c . FILTER(?a != ?c) }";
	private static final String FILTER_PLAIN = "SELECT ?a ?c WHERE { ?a " + P + " ?b . ?b " + Q
			+ " ?c . FILTER(?a != ?c) }";
	private static final String PLAIN_DISTINCT = "SELECT DISTINCT ?a ?c WHERE { ?a " + P + " ?b . ?b " + Q + " ?c }";

	@TempDir
	File dir;

	@Test
	void nativeResidualDistinctKeepsRowsUnderPushedDownFilter() {
		String previous = System.getProperty(FORCE_ROOT_GENERIC);
		System.setProperty(FORCE_ROOT_GENERIC, "true");
		Repository memory = memory();
		Repository lmdb = lmdb("native_filter", true);
		try {
			Map<String, Integer> expected = run(memory, FILTER_DISTINCT, null);
			Map<String, Integer> actual = run(lmdb, FILTER_DISTINCT, null);
			assertThat(expected).isNotEmpty();
			assertThat(actual).hasSameSizeAs(expected);
			assertThat(actual).isEqualTo(expected);
		} finally {
			memory.shutDown();
			lmdb.shutDown();
			if (previous == null) {
				System.clearProperty(FORCE_ROOT_GENERIC);
			} else {
				System.setProperty(FORCE_ROOT_GENERIC, previous);
			}
		}
	}

	@Test
	void defaultPathDistinctUsesPartitionedPlan() {
		Repository memory = memory();
		Repository lmdb = lmdb("default_distinct", false);
		try {
			StringBuilder explain = new StringBuilder();
			Map<String, Integer> expected = run(memory, PLAIN_DISTINCT, null);
			Map<String, Integer> actual = run(lmdb, PLAIN_DISTINCT, explain);
			assertThat(actual).isEqualTo(expected);
			assertThat(explain.toString()).as("leading pattern should be planned on an index order")
					.contains("statementOrder");
		} finally {
			memory.shutDown();
			lmdb.shutDown();
		}
	}

	@Test
	void defaultPathDistinctEvaluatesWithPartitionedIteration() {
		Repository memory = memory();
		Repository lmdb = lmdb("default_distinct_counter", false);
		try {
			long before = LmdbPartitionedDistinctSteps.partitionedEvaluationCount();
			Map<String, Integer> expected = run(memory, PLAIN_DISTINCT, null);
			Map<String, Integer> actual = run(lmdb, PLAIN_DISTINCT, null);
			assertThat(actual).isEqualTo(expected);
			assertThat(LmdbPartitionedDistinctSteps.partitionedEvaluationCount())
					.as("the DISTINCT should have been evaluated by the partitioned iteration")
					.isGreaterThan(before);
		} finally {
			memory.shutDown();
			lmdb.shutDown();
		}
	}

	@Test
	void experimentalOptimizationsOffRestoresPlainDistinct() {
		Repository memory = memory();
		Repository lmdb = lmdb("experimental_off", false, false);
		try {
			long before = LmdbPartitionedDistinctSteps.partitionedEvaluationCount();
			StringBuilder explain = new StringBuilder();
			Map<String, Integer> expected = run(memory, PLAIN_DISTINCT, null);
			Map<String, Integer> actual = run(lmdb, PLAIN_DISTINCT, explain);
			assertThat(actual).isEqualTo(expected);
			assertThat(explain.toString()).doesNotContain("statementOrder");
			assertThat(LmdbPartitionedDistinctSteps.partitionedEvaluationCount()).isEqualTo(before);
		} finally {
			memory.shutDown();
			lmdb.shutDown();
		}
	}

	@Test
	void pendingTransactionChangesDisablePartitionedDistinct() {
		Repository lmdb = lmdb("pending", false);
		try (RepositoryConnection conn = lmdb.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			conn.begin();
			conn.add(vf.createIRI("urn:a0"), vf.createIRI("urn:p"), vf.createIRI("urn:fresh"));
			conn.add(vf.createIRI("urn:fresh"), vf.createIRI("urn:q"), vf.createIRI("urn:cfresh"));
			long before = LmdbPartitionedDistinctSteps.partitionedEvaluationCount();
			TupleQuery tupleQuery = conn.prepareTupleQuery(QueryLanguage.SPARQL, PLAIN_DISTINCT);
			String explain = tupleQuery.explain(Explanation.Level.Executed).toString();
			int rows = 0;
			try (var result = tupleQuery.evaluate()) {
				while (result.hasNext()) {
					result.next();
					rows++;
				}
			}
			conn.rollback();
			// 14882 committed distinct rows plus the (urn:a0, urn:cfresh) row only visible in the transaction
			assertThat(rows).isEqualTo(14883);
			assertThat(explain).doesNotContain("statementOrder");
			assertThat(LmdbPartitionedDistinctSteps.partitionedEvaluationCount()).isEqualTo(before);
		} finally {
			lmdb.shutDown();
		}
	}

	private void load(Repository repo) {
		Random rnd = new Random(42);
		int nA = 3000;
		int nB = 40;
		int nC = 7;
		List<String[]> triples = new ArrayList<>();
		for (int a = 0; a < nA; a++) {
			for (int k = 0; k < 4; k++) {
				triples.add(new String[] { "a" + a, "p", "b" + rnd.nextInt(nB) });
			}
		}
		for (int b = 0; b < nB; b++) {
			triples.add(new String[] { "b" + b, "q", "c" + rnd.nextInt(nC) });
			triples.add(new String[] { "b" + b, "q", "c" + rnd.nextInt(nC) });
		}
		Collections.shuffle(triples, rnd);
		try (RepositoryConnection conn = repo.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			conn.begin();
			for (String[] t : triples) {
				IRI s = vf.createIRI("urn:" + t[0]);
				IRI p = vf.createIRI("urn:" + t[1]);
				IRI o = vf.createIRI("urn:" + t[2]);
				conn.add(s, p, o);
			}
			conn.commit();
		}
	}

	private Repository lmdb(String sub, boolean nativeEnabled) {
		return lmdb(sub, nativeEnabled, true);
	}

	private Repository lmdb(String sub, boolean nativeEnabled, boolean experimental) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(nativeEnabled);
		config.setExperimentalQueryOptimizations(experimental);
		LmdbStore store = new LmdbStore(new File(dir, sub), config);
		SailRepository repo = new SailRepository(store);
		repo.init();
		load(repo);
		return repo;
	}

	private Repository memory() {
		SailRepository repo = new SailRepository(new MemoryStore());
		repo.init();
		load(repo);
		return repo;
	}

	private static Map<String, Integer> run(Repository repo, String query, StringBuilder explainOut) {
		try (RepositoryConnection conn = repo.getConnection()) {
			Map<String, Integer> counts = new LinkedHashMap<>();
			TupleQuery tupleQuery = conn.prepareTupleQuery(QueryLanguage.SPARQL, query);
			if (explainOut != null) {
				explainOut.append(tupleQuery.explain(Explanation.Level.Executed));
			}
			try (var result = tupleQuery.evaluate()) {
				while (result.hasNext()) {
					BindingSet bindingSet = result.next();
					List<String> parts = new ArrayList<>();
					for (String name : new TreeSet<>(bindingSet.getBindingNames())) {
						parts.add(name + "=" + bindingSet.getValue(name));
					}
					counts.merge(parts.toString(), 1, Integer::sum);
				}
			}
			return counts;
		}
	}
}
